/**
 * Java Mapper 生成器
 * IR → 视图映射骨架
 *
 * 对带 from 声明的视图，生成映射方法骨架：
 *   - 有 from 的字段：自动生成取值 + 类型转换
 *   - 无 from 的字段：生成 TODO 占位
 * 人只需填 TODO，其余自动。
 *
 * 输出：generated/assembler/XxxAssembler.java
 */
import { writeFileSync, mkdirSync, existsSync, rmSync } from 'fs'
import { join } from 'path'

const HEADER = [
  '// AUTO-GENERATED by polyforge. DO NOT EDIT.',
  '// 源：模型定义的 views（from 声明）',
  '',
]

const PKG = 'com.we.engine.server.generated.assembler'
const PKG_DTO = 'com.we.engine.server.generated.dto'
const PKG_ENTITY = 'com.we.engine.server.generated.entity'
const PKG_ENUM = 'com.we.engine.server.generated.enums'

function cap(s) { return s.charAt(0).toUpperCase() + s.slice(1) }
function lower(s) { return s.charAt(0).toLowerCase() + s.slice(1) }

/** 实体字段 → Java 类型名（用于判断转换） */
function entityFieldJavaType(fd) {
  if (!fd) return 'String'
  if (fd.type === 'id') return (fd.idType === 'long' || !fd.idType) ? 'Long' : 'String'
  const map = {
    string: 'String', text: 'String', int: 'Integer', long: 'Long',
    number: 'BigDecimal', decimal: 'BigDecimal', boolean: 'Boolean',
    date: 'LocalDate', datetime: 'OffsetDateTime', json: 'String',
  }
  if (fd.resolved?.kind === 'enum' || fd.resolved?.kind === 'entity') return fd.resolved.target
  return map[fd.type] || 'String'
}

/** 视图字段 → Java 类型名 */
function viewFieldJavaType(fd) {
  if (!fd) return 'String'
  if (fd.type === 'id') return (fd.idType === 'long' || !fd.idType) ? 'Long' : 'String'
  const map = {
    string: 'String', text: 'String', int: 'Integer', long: 'Long',
    number: 'BigDecimal', decimal: 'BigDecimal', boolean: 'Boolean',
    date: 'LocalDate', datetime: 'OffsetDateTime', json: 'Object',
  }
  if (fd.resolved?.kind === 'enum' || fd.resolved?.kind === 'view') return fd.resolved.target
  return map[fd.type] || 'String'
}

/** 生成取值表达式（含类型转换） */
function buildExpr(fromRef, entField, viewField, entityVar) {
  const [entName, fname] = fromRef.split('.')
  const getter = entityVar + '.' + 'get' + cap(fname) + '()'
  const entType = entityFieldJavaType(entField)
  const viewType = viewFieldJavaType(viewField)
  if (entType === viewType) return getter
  // Long → String 转换
  if (entType === 'Long' && viewType === 'String') return 'String.valueOf(' + getter + ')'
  if (entType === 'Integer' && viewType === 'String') return 'String.valueOf(' + getter + ')'
  // 其他：留 TODO
  return getter + ' /* TODO 类型转换: ' + entType + ' → ' + viewType + ' */'
}

function renderMapper(viewName, view, ir) {
  const fields = view.fields || {}

  // 收集用到的实体
  const usedEntities = new Set()
  for (const fd of Object.values(fields)) {
    if (fd.from) usedEntities.add(String(fd.from).split('.')[0])
  }

  // 无 from 且无 entity 依赖 → 不生成 mapper
  if (usedEntities.size === 0) return null

  const entityParams = [...usedEntities].sort().map((e) => e + ' ' + lower(e))
  const method = 'to' + viewName

  const lines = [...HEADER]
  lines.push('package ' + PKG + ';')
  lines.push('')
  lines.push('import ' + PKG_DTO + '.' + viewName + ';')
  for (const e of [...usedEntities].sort()) {
    lines.push('import ' + PKG_ENTITY + '.' + e + ';')
  }
  lines.push('')
  lines.push('public class ' + viewName + 'Assembler {')
  lines.push('')
  lines.push('    /**')
  lines.push('     * ' + viewName + ' 映射骨架。')
  lines.push('     * 有 from 的字段已自动填充；TODO 字段需手写。')
  lines.push('     */')
  lines.push('    public static ' + viewName + ' ' + method + '(' + entityParams.join(', ') + ') {')
  lines.push('        return new ' + viewName + '(')

  const argLines = []
  for (const [fn, fd] of Object.entries(fields)) {
    if (fd.writeOnly && view.viewKind !== 'form') continue
    if (fd.from) {
      const entName = String(fd.from).split('.')[0]
      const fname = String(fd.from).split('.')[1]
      const ent = ir.entities.get(entName)
      const entField = ent?.fields?.[fname]
      const expr = buildExpr(fd.from, entField, fd, lower(entName))
      argLines.push('                ' + expr + ',   // from ' + fd.from)
    } else {
      argLines.push('                null,   // TODO: ' + fn + '（无来源）')
    }
  }
  // 去掉最后一行的逗号（逗号在行中、注释之前，需按 , 分割处理）
  if (argLines.length > 0) {
    const last = argLines.length - 1
    argLines[last] = argLines[last].replace(/,(\s*\/\/)/, '$1')
  }
  lines.push(argLines.join('\n'))
  lines.push('        );')
  lines.push('    }')
  lines.push('}')
  return lines.join('\n') + '\n'
}

export function generateJavaMapper(ir, outRoot) {
  const dir = join(outRoot, 'assembler')
  // 清理旧产物，保证目录内容与当前 IR 一致
  if (existsSync(dir)) rmSync(dir, { recursive: true, force: true })
  mkdirSync(dir, { recursive: true })

  let count = 0
  for (const [name, view] of ir.views) {
    const code = renderMapper(name, view, ir)
    if (code) {
      writeFileSync(join(dir, name + 'Assembler.java'), code, 'utf-8')
      count++
    }
  }
  console.log('  [java/assembler] ' + count + ' 个视图映射器 → ' + dir)
}
